class Solution {
public:
    vector<int> findMode(TreeNode* root) {
        unordered_map<int, int> freq; // frequency map
        int maxFreq = 0; // maximum frequency so far
        traverse(root, freq, maxFreq); // traverse the tree and update the frequency map
        vector<int> modes; // output vector
        for (auto [key, count] : freq) { // loop over the frequency map
            if (count == maxFreq) { // if the current key has maximum frequency
                modes.push_back(key); // add it to the output
            }
        }
        return modes;
    }
private:
    void traverse(TreeNode* root, unordered_map<int, int>& freq, int& maxFreq) {
        if (!root) return;
        traverse(root->left, freq, maxFreq);
