class Solution {
    public List<Integer> preorderTraversal(TreeNode root) {
        List<Integer> result = new ArrayList<Integer>();
        traverseTree(root, result);
        return result;
    }

    public void traverseTree(TreeNode node, List<Integer> resultList){
        if(node == null) {
            return;
        }
        resultList.add(node.val);
        traverseTree(node.left, resultList);
        traverseTree(node.right, resultList);
    }
}
